import re

rute = []


def tambah(metode, pola, handler):
    # "/produk/{id}" diubah jadi regex "^/produk/(?P<id>[^/]+)$"
    regex = "^" + re.sub(r"\{(\w+)\}", r"(?P<\1>[^/]+)", pola) + "$"
    rute.append((metode, re.compile(regex), handler))


def cari(metode, path):
    for m, regex, handler in rute:
        cocok = regex.match(path)
        if cocok and m == metode:
            return handler, cocok.groupdict()
    return None, {}


