import json


def validasi(data):
    """Kumpulkan semua kesalahan sekaligus, jangan berhenti di yang pertama."""
    galat = []
    nama = data.get("nama")
    if not isinstance(nama, str) or not nama.strip():
        galat.append({"field": "nama", "pesan": "wajib diisi"})
    umur = data.get("umur")
    if not isinstance(umur, int) or isinstance(umur, bool):
        galat.append({"field": "umur", "pesan": "harus bilangan bulat"})
    elif umur < 13:
        galat.append({"field": "umur", "pesan": "minimal 13"})
    if "@" not in str(data.get("email", "")):
        galat.append({"field": "email", "pesan": "format email salah"})
    return galat


def daftar(teks):
    try:
        data = json.loads(teks)
    except json.JSONDecodeError as e:
        return 400, {"type": "about:blank", "title": "Bad Request",
                     "status": 400, "detail": f"JSON rusak di kolom {e.colno}"}
    galat = validasi(data) if isinstance(data, dict) else [
        {"field": "", "pesan": "body harus objek JSON"}]
    if galat:
        return 422, {"type": "https://toko.test/masalah/validasi",
                     "title": "Data pendaftaran nggak sah", "status": 422,
                     "detail": f"{len(galat)} field bermasalah",
                     "errors": galat}
    return 201, {"nama": data["nama"]}


