ASAL_DIIZINKAN = {"https://toko.test", "https://admin.toko.test"}


def header_cors(metode, origin, metode_diminta=None):
    """Header CORS yang ditambahkan server ke respons."""
    if origin not in ASAL_DIIZINKAN:
        return {}                 # tanpa header: browser yang memblokir
    header = {"Access-Control-Allow-Origin": origin, "Vary": "Origin"}
    if metode == "OPTIONS" and metode_diminta:      # ini preflight
        header["Access-Control-Allow-Methods"] = "GET, POST, PATCH, DELETE"
        header["Access-Control-Allow-Headers"] = "Content-Type, Authorization"
        header["Access-Control-Max-Age"] = "600"
    return header


