def cocok(pola, kunci):
    p, k = pola.split("."), kunci.split(".")

    def jalan(i, j):
        if i == len(p):
            return j == len(k)
        if p[i] == "#":
            return any(jalan(i + 1, x) for x in range(j, len(k) + 1))
        if j < len(k) and (p[i] == "*" or p[i] == k[j]):
            return jalan(i + 1, j + 1)
        return False

    return jalan(0, 0)


