import json


def varint(n):
    hasil = bytearray()
    while True:
        tujuh = n & 0x7F
        n >>= 7
        if n:
            hasil.append(tujuh | 0x80)
        else:
            hasil.append(tujuh)
            return bytes(hasil)


def field_angka(nomor, nilai):
    return varint(nomor << 3 | 0) + varint(nilai)


def field_teks(nomor, teks):
    data = teks.encode("utf-8")
    return varint(nomor << 3 | 2) + varint(len(data)) + data


