import re
import sys

RUTE = [
    ("GET", "/users", "daftar_user"),
    ("POST", "/users", "buat_user"),
    ("GET", "/users/{id}", "lihat_user"),
    ("DELETE", "/users/{id}", "hapus_user"),
    ("GET", "/users/{id}/posts/{post_id}", "lihat_post"),
]


def jadi_regex(pola):
    return re.compile("^" + re.sub(r"\{(\w+)\}", r"(?P<\1>[^/]+)", pola) + "$")


TABEL = [(m, jadi_regex(p), h) for m, p, h in RUTE]


def cocokkan(metode, path):
    metode_lain = set()
    for m, regex, handler in TABEL:
        hasil = regex.match(path)
        if not hasil:
            continue
        if m == metode:
            return 200, handler, hasil.groupdict()
        metode_lain.add(m)
    if metode_lain:
        return 405, None, sorted(metode_lain)
    return 404, None, None


