import json
import sys

BARANG = [f"barang-{i:02d}" for i in range(1, 24)]   # 23 item
PER_HALAMAN_MAKS = 20


def masalah(status, title, detail):
    return status, "application/problem+json", {
        "type": "about:blank", "title": title,
        "status": status, "detail": detail}


def bilangan(teks, nama, bawah, atas=None):
    """(angka, None) kalau sah, (None, pesan) kalau nggak."""
    if not teks.isdigit():
        return None, f"{nama} harus bilangan bulat"
    angka = int(teks)
    if angka < bawah or (atas is not None and angka > atas):
        batas = f"{bawah} sampai {atas}" if atas else f"minimal {bawah}"
        return None, f"{nama} harus {batas}"
    return angka, None


def tautan(halaman, per):
    return f"/barang?page={halaman}&per_page={per}"


def daftar_barang(query):
    param = {}
    for potong in query.split("&"):
        if potong:
            kunci, _, nilai = potong.partition("=")
            param[kunci] = nilai
    page, galat = bilangan(param.get("page", "1"), "page", 1)
    if galat:
        return masalah(400, "Bad Request", galat)
    per, galat = bilangan(param.get("per_page", "10"), "per_page", 1,
                          PER_HALAMAN_MAKS)
    if galat:
        return masalah(400, "Bad Request", galat)
    total_halaman = (len(BARANG) + per - 1) // per
    if page > total_halaman:
        return masalah(404, "Not Found",
                       f"halaman {page} nggak ada, total {total_halaman} halaman")
    awal = (page - 1) * per
    body = {
        "data": BARANG[awal:awal + per],
        "meta": {"page": page, "per_page": per, "total": len(BARANG),
                 "total_pages": total_halaman},
        "links": {
            "next": tautan(page + 1, per) if page < total_halaman else None,
            "prev": tautan(page - 1, per) if page > 1 else None,
        },
    }
    return 200, "application/json", body


for query in sys.stdin.read().splitlines():
    status, jenis, body = daftar_barang(query.strip())
    print(f"GET /barang?{query.strip()}")
    print(status, jenis)
    print(json.dumps(body, sort_keys=True, indent=2))

