import re
import sys
from http import HTTPStatus

KONVERTER = {"int": (r"\d+", int), "string": (r"[^/]+", str)}


class App:
    def __init__(self):
        self.rute = []                 # (regex, metode, fungsi, konversi)

    def route(self, pola, methods=("GET",)):
        def daftar(fungsi):
            konversi = {}

            def ganti(cocok):
                jenis, nama = cocok.group(1) or "string", cocok.group(2)
                regex, ubah = KONVERTER[jenis]
                konversi[nama] = ubah
                return f"(?P<{nama}>{regex})"

            regex = re.sub(r"<(?:(\w+):)?(\w+)>", ganti, pola)
            self.rute.append((re.compile(f"^{regex}$"), set(methods),
                              fungsi, konversi))
            return fungsi
        return daftar

    def __call__(self, environ, start_response):
        metode, path = environ["REQUEST_METHOD"], environ["PATH_INFO"]
        izin = set()
        for regex, metode_rute, fungsi, konversi in self.rute:
            cocok = regex.match(path)
            if not cocok:
                continue
            if metode not in metode_rute:
                izin |= metode_rute
                continue
            argumen = {k: konversi[k](v) for k, v in cocok.groupdict().items()}
            hasil = fungsi(**argumen)
            body, kode = hasil if isinstance(hasil, tuple) else (hasil, 200)
            return self.balas(start_response, kode, body)
        if izin:
            return self.balas(start_response, 405, "Allow: " + ", ".join(sorted(izin)))
        return self.balas(start_response, 404, "halaman nggak ada")

    def balas(self, start_response, kode, body):
        status = f"{kode} {HTTPStatus(kode).phrase}"
