import dataclasses
import json
import sys
import typing
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class Pesanan:
    menu: str
    jumlah: int
    harga: float
    pedas: bool = False
    catatan: Optional[str] = None
    tambahan: list[int] = field(default_factory=list)


PESAN = {
    str: "Input should be a valid string",
    int: "Input should be a valid integer",
    float: "Input should be a valid number",
    bool: "Input should be a valid boolean",
    list: "Input should be a valid list",
}


def ubah(nilai, tipe, loc, galat):
    """Ubah nilai ke tipe; kalau gagal, catat galat dan kembalikan None."""
    asal, argumen = typing.get_origin(tipe), typing.get_args(tipe)
    if asal is typing.Union:                      # Optional[X] = Union[X, None]
        if nilai is None:
            return None
        tipe = [a for a in argumen if a is not type(None)][0]
        return ubah(nilai, tipe, loc, galat)
    if asal is list:
        if not isinstance(nilai, list):
            galat.append({"loc": loc, "msg": PESAN[list]})
            return None
        return [ubah(v, argumen[0], loc + [i], galat) for i, v in enumerate(nilai)]
    if tipe is bool:
        if isinstance(nilai, bool):
            return nilai
        if nilai in ("true", "false"):
            return nilai == "true"
    elif tipe is int:
        if isinstance(nilai, int) and not isinstance(nilai, bool):
            return nilai
        if isinstance(nilai, str) and nilai.isdigit():
            return int(nilai)
    elif tipe is float:
        if isinstance(nilai, (int, float)) and not isinstance(nilai, bool):
            return float(nilai)
        if isinstance(nilai, str):
            try:
                return float(nilai)
            except ValueError:
                pass
    elif tipe is str and isinstance(nilai, str):
        return nilai
    galat.append({"loc": loc, "msg": PESAN[tipe]})
    return None


def muat(kelas, data):
    """(objek, []) kalau sah, (None, daftar galat) kalau nggak."""
    petunjuk = typing.get_type_hints(kelas)
    galat, hasil = [], {}
    for f in dataclasses.fields(kelas):
        loc = ["body", f.name]
        if f.name not in data:
            wajib = (f.default is dataclasses.MISSING
                     and f.default_factory is dataclasses.MISSING)
            if wajib:
                galat.append({"loc": loc, "msg": "Field required"})
            continue
        hasil[f.name] = ubah(data[f.name], petunjuk[f.name], loc, galat)
    if galat:
        return None, galat
    return kelas(**hasil), []


for baris in sys.stdin.read().splitlines():
    if not baris.strip():
        continue
    objek, galat = muat(Pesanan, json.loads(baris))
    if objek:
        print("200", objek)
    else:
        print("422")
        for g in galat:
            print("  ", json.dumps(g))

