import re
import sys

TABEL = "pengguna"
PROPERTI = ["name", "email", "age", "active", "createdAt"]
AKHIRAN = [
    ("GreaterThanEqual", ">= ?"), ("LessThanEqual", "<= ?"),
    ("GreaterThan", "> ?"), ("LessThan", "< ?"),
    ("Between", "BETWEEN ? AND ?"), ("Containing", "LIKE ?"),
    ("IsNotNull", "IS NOT NULL"), ("IsNull", "IS NULL"),
    ("Not", "<> ?"), ("True", "= TRUE"), ("False", "= FALSE"),
]
AWALAN = {"find": "SELECT *", "count": "SELECT COUNT(*)", "exists": "SELECT 1"}


def kolom(nama):
    prop = nama[:1].lower() + nama[1:]
    if prop not in PROPERTI:
        raise ValueError(f"properti '{prop}' tidak ada di Pengguna")
    return re.sub(r"([A-Z])", r"_\1", prop).lower()


def syarat(potong, nomor):
    for akhiran, pola in AKHIRAN:
        if potong.endswith(akhiran) and len(potong) > len(akhiran):
            nama, operator = potong[:-len(akhiran)], pola
            break
    else:
        nama, operator = potong, "= ?"
    hasil = ""
    for huruf in operator:
        if huruf == "?":
            hasil += f"?{nomor}"
            nomor += 1
        else:
            hasil += huruf
    return kolom(nama) + " " + hasil, nomor


def terjemahkan(metode):
    cocok = re.fullmatch(r"([a-z]+)By(\w+)", metode)
    if not cocok or cocok.group(1) not in AWALAN:
        awal = cocok.group(1) if cocok else metode
        raise ValueError(f"awalan '{awal}' tidak dikenal (pakai find, count, "
                         "atau exists)")
    awalan, sisa = cocok.groups()
    kriteria, _, urutan = sisa.partition("OrderBy")
    bagian = re.split(r"(?<=[a-z0-9])(And|Or)(?=[A-Z])", kriteria)
    where, nomor = [], 1
    for i, potong in enumerate(bagian):
        if i % 2:
            where.append(potong.upper())
        else:
            teks, nomor = syarat(potong, nomor)
            where.append(teks)
    sql = f"{AWALAN[awalan]} FROM {TABEL} WHERE " + " ".join(where)
    if urutan:
        susunan = []
        for nama, arah in re.findall(r"([A-Z][a-zA-Z]*?)(Asc|Desc)", urutan):
            susunan.append(f"{kolom(nama)} {arah.upper()}")
        sql += " ORDER BY " + ", ".join(susunan)
    if awalan == "exists":
        sql += " LIMIT 1"
    return sql


for baris in sys.stdin.read().split():
    print(baris)
    try:
        print("  " + terjemahkan(baris))
    except ValueError as e:
        print("  galat:", e)

import sys

KOLOM = ["nama", "harga", "stok"]
DB = {
    1: {"nama": "Teh", "harga": 5000, "stok": 10},
    2: {"nama": "Kopi", "harga": 18000, "stok": 5},
    3: {"nama": "Roti", "harga": 12000, "stok": 0},
}


def sql_nilai(v):
    return str(v) if isinstance(v, int) else f"'{v}'"


class Entri:
    def __init__(self, kunci, nilai, keadaan):
        self.kunci = kunci
        self.nilai = dict(nilai)
        self.asli = dict(nilai)
        self.dasar = keadaan

    def keadaan(self):
        if self.dasar in ("Added", "Deleted"):
            return self.dasar
        return "Modified" if self.nilai != self.asli else "Unchanged"


class DbContext:
    def __init__(self):
        self.lacak = {}
        self.nomor_baru = 0

    def load(self, kunci):
        kunci = int(kunci)
        if kunci not in DB:
            return f"galat: produk {kunci} tidak ada"
        self.lacak.setdefault(kunci, Entri(kunci, DB[kunci], "Unchanged"))
        return None

    def ambil(self, kunci):
        kunci = int(kunci) if kunci.isdigit() else kunci
        if kunci not in self.lacak:
            raise KeyError(f"galat: produk {kunci} belum dimuat")
        return self.lacak[kunci]

    def set(self, kunci, kolom, nilai):
        e = self.ambil(kunci)
        e.nilai[kolom] = int(nilai) if nilai.isdigit() else nilai

    def add(self, nama, harga, stok):
        self.nomor_baru += 1
        kunci = f"baru{self.nomor_baru}"
        nilai = {"nama": nama, "harga": int(harga), "stok": int(stok)}
        self.lacak[kunci] = Entri(kunci, nilai, "Added")
        return kunci

    def remove(self, kunci):
        e = self.ambil(kunci)
        if e.dasar == "Added":
            del self.lacak[e.kunci]      # belum pernah disimpan: cukup lupakan
        else:
            e.dasar = "Deleted"

    def urut(self):
        lama = sorted(k for k in self.lacak if isinstance(k, int))
        baru = [k for k in self.lacak if not isinstance(k, int)]
        return [self.lacak[k] for k in lama + baru]

    def status(self):
        isi = [f"{e.kunci} {e.keadaan()}" for e in self.urut()]
        return "status: " + (", ".join(isi) if isi else "kosong")

    def save_changes(self):
        perintah = []
        for e in self.urut():
            if e.keadaan() == "Added":
                kunci = max(DB) + 1
                DB[kunci] = dict(e.nilai)
                nilai = ", ".join(sql_nilai(e.nilai[k]) for k in KOLOM)
                perintah.append(f"INSERT INTO produk (nama, harga, stok) "
                                f"VALUES ({nilai})  -- {e.kunci} jadi id {kunci}")
                del self.lacak[e.kunci]
                self.lacak[kunci] = Entri(kunci, e.nilai, "Unchanged")
        for e in self.urut():
            if e.keadaan() == "Modified":
                ubah = [k for k in KOLOM if e.nilai[k] != e.asli[k]]
                isi = ", ".join(f"{k} = {sql_nilai(e.nilai[k])}" for k in ubah)
                perintah.append(f"UPDATE produk SET {isi} WHERE id = {e.kunci}")
                DB[e.kunci] = dict(e.nilai)
                e.asli = dict(e.nilai)
        for e in self.urut():
            if e.keadaan() == "Deleted":
                perintah.append(f"DELETE FROM produk WHERE id = {e.kunci}")
                del DB[e.kunci]
                del self.lacak[e.kunci]
        if not perintah:
            return ["tidak ada perubahan"]
        return perintah + [f"disimpan: {len(perintah)} perintah"]


