CREATE TABLE kategori (id INTEGER PRIMARY KEY, nama TEXT);
CREATE TABLE produk (id INTEGER PRIMARY KEY, nama TEXT, harga INTEGER,
                     kategori_id INTEGER);
""")
OPERATOR = {"=", "!=", ">", "<", ">=", "<="}


def jalankan(sql, nilai=()):
    print(f"  SQL: {sql} {list(nilai)}")
    return db.execute(sql, nilai)


class Model:
    tabel = ""
    kolom = []

    def __init__(self, **data):
        self.id = data.pop("id", None)
        self.data = dict(data)
        self.asli = dict(data)

    def __repr__(self):
        isi = ", ".join(f"{k}={self.data[k]}" for k in self.kolom)
        return f"{type(self).__name__}(id={self.id}, {isi})"

    @classmethod
    def periksa(cls, nama):
        if nama not in cls.kolom and nama != "id":
            raise ValueError(f"kolom '{nama}' tidak ada di {cls.tabel}")

    @classmethod
    def dari_baris(cls, baris):
        return cls(**dict(zip(["id"] + cls.kolom, baris)))

    @classmethod
    def create(cls, **data):
        for nama in data:
            cls.periksa(nama)
        obj = cls(**{k: data.get(k) for k in cls.kolom})
        obj.save()
        return obj

    @classmethod
    def find(cls, kunci):
        baris = jalankan(f"SELECT * FROM {cls.tabel} WHERE id = ?",
                         [kunci]).fetchone()
        return cls.dari_baris(baris) if baris else None

    @classmethod
    def where(cls, nama, op, nilai):
        cls.periksa(nama)
        if op not in OPERATOR:
            raise ValueError(f"operator '{op}' tidak dikenal")
        sql = f"SELECT * FROM {cls.tabel} WHERE {nama} {op} ? ORDER BY id"
        return [cls.dari_baris(b) for b in jalankan(sql, [nilai]).fetchall()]

    def save(self):
        if self.id is None:
            daftar = ", ".join(self.kolom)
            tanda = ", ".join("?" for _ in self.kolom)
            sql = f"INSERT INTO {self.tabel} ({daftar}) VALUES ({tanda})"
            self.id = jalankan(sql, [self.data[k] for k in self.kolom]).lastrowid
        else:
            berubah = [k for k in self.kolom if self.data[k] != self.asli[k]]
            if not berubah:
                print("  tidak ada perubahan, tidak ada SQL")
                return
            isi = ", ".join(f"{k} = ?" for k in berubah)
            jalankan(f"UPDATE {self.tabel} SET {isi} WHERE id = ?",
                     [self.data[k] for k in berubah] + [self.id])
        self.asli = dict(self.data)

    def delete(self):
        jalankan(f"DELETE FROM {self.tabel} WHERE id = ?", [self.id])

    def has_many(self, kelas, kunci_asing):
        sql = f"SELECT * FROM {kelas.tabel} WHERE {kunci_asing} = ? ORDER BY id"
        return [kelas.dari_baris(b) for b in jalankan(sql, [self.id]).fetchall()]


class Kategori(Model):
    tabel = "kategori"
    kolom = ["nama"]

    def produk(self):
        return self.has_many(Produk, "kategori_id")


class Produk(Model):
