import re
import sys

URUTAN = [
    ("index", "GET", ""), ("create", "POST", ""), ("new", "GET", "/new"),
    ("edit", "GET", "/:id/edit"), ("show", "GET", "/:id"),
    ("update", "PATCH", "/:id"), ("update", "PUT", "/:id"),
    ("destroy", "DELETE", "/:id"),
]
AKSI = {"index", "create", "new", "edit", "show", "update", "destroy"}
POLA = re.compile(r"resources :(\w+)(?:, (only|except): \[([^\]]*)\])?( do)?$")


def tunggal(nama):
    if nama.endswith("ies"):
        return nama[:-3] + "y"
    return nama[:-1] if nama.endswith("s") else nama


def rute(nama, pilihan, daftar, induk):
    aksi = set(AKSI)
    if pilihan:
        dipilih = {a.strip().lstrip(":") for a in daftar.split(",") if a.strip()}
        asing = sorted(dipilih - AKSI)
        if asing:
            raise ValueError(f"aksi '{asing[0]}' tidak dikenal")
        aksi = dipilih if pilihan == "only" else AKSI - dipilih
    awal = f"/{induk}/:{tunggal(induk)}_id" if induk else ""
    return [(verb, f"{awal}/{nama}{akhir}", f"{nama}#{a}")
            for a, verb, akhir in URUTAN if a in aksi]


