import sys


def urai(teks):
    """'GET /items/{id}' -> (metode atau None, daftar segmen)."""
    metode, _, jalur = teks.rpartition(" ")
    potong = jalur.split("/")[1:]
    segmen = []
    for i, s in enumerate(potong):
        akhir = i == len(potong) - 1
        if s == "{$}":
            segmen.append(("akhir", None))
        elif s.startswith("{") and s.endswith("...}"):
            segmen.append(("sisa", s[1:-4]))
        elif s.startswith("{") and s.endswith("}"):
            segmen.append(("liar", s[1:-1]))
        elif s == "" and akhir and i > 0:
            segmen.append(("sisa", None))      # garis miring di ujung
        elif s == "" and akhir:
            segmen.append(("sisa", None))      # pola "/" saja
        else:
            segmen.append(("lit", s))
    return (metode or None), segmen


def subset(a, b):
    """Apakah setiap jalur yang cocok dengan a juga cocok dengan b?"""
    if not a or not b:
        return not a and not b
    (ja, na), (jb, nb) = a[0], b[0]
    if jb == "sisa":
        return True
    if ja == "sisa":
        return False
    if ja == "akhir" or jb == "akhir":
        return ja == jb
    if jb == "liar" or (ja == "lit" and na == nb):
        return subset(a[1:], b[1:])
    return False


def tumpang(a, b):
    """Apakah ada jalur yang cocok dengan a dan b sekaligus?"""
    if not a or not b:
        return not a and not b
    (ja, na), (jb, nb) = a[0], b[0]
    if ja == "sisa" or jb == "sisa":
        return True
    if ja == "akhir" or jb == "akhir":
        return ja == jb
    if ja == "lit" and jb == "lit" and na != nb:
        return False
    return tumpang(a[1:], b[1:])


def lebih_spesifik(p, q):
    (mp, sp), (mq, sq) = p, q
    p_dalam_q = subset(sp, sq) and (mq is None or mp == mq)
    q_dalam_p = subset(sq, sp) and (mp is None or mp == mq)
    return p_dalam_q and not q_dalam_p


def cocok(segmen, potong):
    """Nilai wildcard (dict) kalau jalur cocok, None kalau tidak."""
    nilai = {}
    for i, (jenis, nama) in enumerate(segmen):
        if jenis == "sisa":
            if i >= len(potong):
                return None
            if nama:
                nilai[nama] = "/".join(potong[i:])
            return nilai
        if i >= len(potong):
            return None
        if jenis == "akhir":
            return nilai if potong[i:] == [""] else None
        if jenis == "liar":
            if potong[i] == "":
                return None
            nilai[nama] = potong[i]
        elif potong[i] != nama:
            return None
    return nilai if len(potong) == len(segmen) else None


terdaftar = []
