import json
import sys


def tambah(a, b):
    return a + b


def kurang(a, b):
    return a - b


def sapa(nama):
    return f"Halo, {nama}!"


METODE = {"tambah": tambah, "kurang": kurang, "sapa": sapa}
ARGUMEN = {"tambah": ["a", "b"], "kurang": ["a", "b"], "sapa": ["nama"]}


def galat(kode, pesan, id_=None):
    return {"jsonrpc": "2.0", "error": {"code": kode, "message": pesan},
            "id": id_}


def satu(req):
    if (not isinstance(req, dict) or req.get("jsonrpc") != "2.0"
            or not isinstance(req.get("method"), str)
            or ("params" in req and not isinstance(req["params"], (list, dict)))):
        return galat(-32600, "Invalid Request")
    notifikasi = "id" not in req
    id_ = req.get("id")
    nama = req["method"]
    if nama not in METODE:
        return None if notifikasi else galat(-32601, "Method not found", id_)
    params = req.get("params", [])
    harap = ARGUMEN[nama]
    if isinstance(params, dict):
        if sorted(params) != sorted(harap):
            return None if notifikasi else galat(-32602, "Invalid params", id_)
        args = [params[k] for k in harap]
    else:
        if len(params) != len(harap):
            return None if notifikasi else galat(-32602, "Invalid params", id_)
        args = params
    try:
        hasil = METODE[nama](*args)
    except TypeError:
        return None if notifikasi else galat(-32602, "Invalid params", id_)
    if notifikasi:
        return None
    return {"jsonrpc": "2.0", "result": hasil, "id": id_}


def handle(teks):
    try:
        data = json.loads(teks)
    except json.JSONDecodeError:
        return json.dumps(galat(-32700, "Parse error"))
    if isinstance(data, list):
        if not data:
            return json.dumps(galat(-32600, "Invalid Request"))
        jawab = [r for r in (satu(x) for x in data) if r is not None]
        return json.dumps(jawab) if jawab else None
    r = satu(data)
    return None if r is None else json.dumps(r)


for baris in sys.stdin.read().splitlines():
    if not baris.strip():
        continue
    keluar = handle(baris)
    print(keluar if keluar is not None else "(tanpa respons)")

import base64
import hashlib
import hmac
import json
import sys

KUNCI_JWT = b"kunci-rahasia-proyek"
GARAM = b"garam-tetap"
PENGGUNA = {"budi": hashlib.pbkdf2_hmac("sha256", b"rahasia123", GARAM, 1000).hex()}
KAPASITAS, MAKS_JUDUL, MAKS_PER_PAGE = 5, 60, 50
ALASAN = {200: "OK", 201: "Created", 204: "No Content", 400: "Bad Request",
          401: "Unauthorized", 404: "Not Found", 405: "Method Not Allowed",
          422: "Unprocessable Content", 429: "Too Many Requests"}


def b64(data):
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()


def unb64(teks):
    return base64.urlsafe_b64decode(teks + "=" * (-len(teks) % 4))


def kompak(obj):
    return json.dumps(obj, separators=(",", ":"))


def buat_jwt(sub, sekarang):
    kepala = b64(kompak({"alg": "HS256", "typ": "JWT"}).encode())
    isi = b64(kompak({"sub": sub, "exp": sekarang + 3600}).encode())
    tanda = hmac.new(KUNCI_JWT, f"{kepala}.{isi}".encode(), "sha256").digest()
    return f"{kepala}.{isi}.{b64(tanda)}"


def cek_jwt(token, sekarang):
    try:
        kepala, isi, tanda = token.split(".")
        h = json.loads(unb64(kepala))
        p = json.loads(unb64(isi))
    except ValueError:
        return None, "token rusak"
    if h.get("alg") != "HS256":
        return None, "algoritma tidak diizinkan"
    harap = hmac.new(KUNCI_JWT, f"{kepala}.{isi}".encode(), "sha256").digest()
    if not hmac.compare_digest(b64(harap), tanda):
        return None, "tanda tangan tidak cocok"
    if sekarang >= p.get("exp", 0):
        return None, "token kedaluwarsa"
    return p["sub"], None


def respons(status, body=None, header=None, jenis="application/json"):
    return {"status": status, "body": body, "header": header or {}, "jenis": jenis}


def masalah(status, detail, **tambahan):
    body = {"type": "about:blank", "title": ALASAN[status], "status": status,
            "detail": detail}
    body.update(tambahan)
    return respons(status, body, jenis="application/problem+json")


# ------------------------------------------------------------------ handler

def h_login(req, ctx, param):
    try:
        data = json.loads(req["body"] or "")
    except ValueError:
        return masalah(400, "body bukan JSON yang sah")
    nama, sandi = data.get("username"), data.get("password")
    simpan = PENGGUNA.get(nama)
    hitung = hashlib.pbkdf2_hmac("sha256", str(sandi).encode(), GARAM, 1000).hex()
    if simpan is None or not hmac.compare_digest(simpan, hitung):
        return masalah(401, "username atau password salah")
    return respons(200, {"token": buat_jwt(nama, ctx["now"])})


def validasi(data, sebagian):
    galat = []
    if not isinstance(data, dict):
        return [{"field": "/", "msg": "harus objek JSON"}]
    if "judul" in data:
        j = data["judul"]
        if not isinstance(j, str) or not j.strip():
            galat.append({"field": "judul", "msg": "harus teks yang tidak kosong"})
        elif len(j) > MAKS_JUDUL:
            galat.append({"field": "judul", "msg": f"paling panjang {MAKS_JUDUL} huruf"})
    elif not sebagian:
        galat.append({"field": "judul", "msg": "wajib diisi"})
    if "selesai" in data and not isinstance(data["selesai"], bool):
        galat.append({"field": "selesai", "msg": "harus true atau false"})
    return galat


def baca_json(req):
    try:
        return json.loads(req["body"] or ""), None
    except ValueError:
        return None, masalah(400, "body bukan JSON yang sah")


def h_buat(req, ctx, param):
    data, salah = baca_json(req)
    if salah:
        return salah
    galat = validasi(data, sebagian=False)
    if galat:
        return masalah(422, "data tugas tidak valid", errors=galat)
    db = ctx["db"]
    db["urut"] += 1
    tugas = {"id": db["urut"], "judul": data["judul"].strip(),
             "selesai": data.get("selesai", False)}
    db["tugas"][tugas["id"]] = tugas
    return respons(201, tugas, {"Location": f"/tugas/{tugas['id']}"})


def angka_query(query, nama, bawaan):
    if nama not in query:
        return bawaan
    teks = query[nama]
    return int(teks) if teks.isdigit() and int(teks) >= 1 else None


def h_daftar(req, ctx, param):
    page = angka_query(req["query"], "page", 1)
    per_page = angka_query(req["query"], "per_page", 10)
    if page is None or per_page is None or per_page > MAKS_PER_PAGE:
        return masalah(400, f"page dan per_page harus bilangan bulat 1..{MAKS_PER_PAGE}")
    semua = [ctx["db"]["tugas"][k] for k in sorted(ctx["db"]["tugas"])]
    total = len(semua)
    halaman = max(1, -(-total // per_page))
    data = semua[(page - 1) * per_page: page * per_page]

    def tautan(p):
        return f"/tugas?page={p}&per_page={per_page}"

    return respons(200, {
        "data": data,
        "meta": {"page": page, "per_page": per_page, "total": total,
                 "total_pages": halaman},
        "links": {"next": tautan(page + 1) if page < halaman else None,
                  "prev": tautan(page - 1) if 1 < page <= halaman else None},
    })


def ambil(ctx, param):
    return ctx["db"]["tugas"].get(int(param["id"]))


def h_satu(req, ctx, param):
    tugas = ambil(ctx, param)
    if tugas is None:
        return masalah(404, f"tugas {param['id']} tidak ada")
    return respons(200, tugas)


def h_ubah(req, ctx, param):
    tugas = ambil(ctx, param)
    if tugas is None:
        return masalah(404, f"tugas {param['id']} tidak ada")
    data, salah = baca_json(req)
    if salah:
        return salah
    galat = validasi(data, sebagian=True)
    if galat:
        return masalah(422, "data tugas tidak valid", errors=galat)
    if "judul" in data:
        tugas["judul"] = data["judul"].strip()
    if "selesai" in data:
        tugas["selesai"] = data["selesai"]
    return respons(200, tugas)


def h_hapus(req, ctx, param):
    if ambil(ctx, param) is None:
        return masalah(404, f"tugas {param['id']} tidak ada")
    del ctx["db"]["tugas"][int(param["id"])]
    return respons(204)


RUTE = [
    ("POST", "/login", h_login, False),
    ("GET", "/tugas", h_daftar, True),
    ("POST", "/tugas", h_buat, True),
    ("GET", "/tugas/{id:int}", h_satu, True),
    ("PATCH", "/tugas/{id:int}", h_ubah, True),
    ("DELETE", "/tugas/{id:int}", h_hapus, True),
]


def cocok(pola, path):
    a, b = pola.strip("/").split("/"), path.strip("/").split("/")
    if len(a) != len(b):
        return None
    param = {}
    for x, y in zip(a, b):
        if x.startswith("{"):
            nama, _, jenis = x[1:-1].partition(":")
            if jenis == "int" and not y.isdigit():
                return None
            param[nama] = y
        elif x != y:
            return None
    return param


def cari_rute(metode, path):
    izin = []
    for m, pola, handler, butuh_auth in RUTE:
        param = cocok(pola, path)
        if param is None:
            continue
        if m == metode:
            return handler, param, butuh_auth, None
        izin.append(m)
    return None, None, None, izin


# --------------------------------------------------------------- middleware

def mw_log(req, ctx, lanjut):
    hasil = lanjut(req, ctx)
    ctx["log"].append(f"t={ctx['now']} {ctx['ip']} {req['method']} {req['path']} "
                      f"-> {hasil['status']}")
    return hasil


def mw_rate_limit(req, ctx, lanjut):
    ember = ctx["ember"].setdefault(ctx["ip"], [KAPASITAS, ctx["now"]])
    ember[0] = min(KAPASITAS, ember[0] + (ctx["now"] - ember[1]))
    ember[1] = ctx["now"]
    if ember[0] < 1:
        hasil = masalah(429, "terlalu banyak permintaan, tunggu sebentar")
        hasil["header"]["Retry-After"] = "1"
        return hasil
    ember[0] -= 1
    return lanjut(req, ctx)


def mw_auth_dan_rute(req, ctx, lanjut):
    handler, param, butuh_auth, izin = cari_rute(req["method"], req["path"])
    if handler is None:
        if izin:
            hasil = masalah(405, f"metode {req['method']} tidak didukung di {req['path']}")
            hasil["header"]["Allow"] = ", ".join(izin)
            return hasil
        return masalah(404, f"tidak ada rute untuk {req['path']}")
    if butuh_auth:
        auth = req["header"].get("authorization", "")
        if not auth.startswith("Bearer "):
            hasil = masalah(401, "butuh header Authorization: Bearer <token>")
            hasil["header"]["WWW-Authenticate"] = "Bearer"
            return hasil
        sub, alasan = cek_jwt(auth[7:], ctx["now"])
        if sub is None:
            hasil = masalah(401, alasan)
            hasil["header"]["WWW-Authenticate"] = 'Bearer error="invalid_token"'
            return hasil
        ctx["user"] = sub
    return handler(req, ctx, param)


RANTAI = [mw_log, mw_rate_limit, mw_auth_dan_rute]


def jalankan_rantai(req, ctx, i=0):
    if i == len(RANTAI):
        return masalah(404, "akhir rantai")
    return RANTAI[i](req, ctx, lambda r, c: jalankan_rantai(r, c, i + 1))


# ---------------------------------------------------------------- HTTP teks

def urai_permintaan(teks):
    kepala, _, body = teks.partition("\n\n")
    baris = kepala.split("\n")
    metode, target, _ = baris[0].split(" ")
    path, _, qs = target.partition("?")
    query = dict(p.split("=", 1) for p in qs.split("&") if "=" in p)
    header = {}
    for b in baris[1:]:
        nama, _, nilai = b.partition(":")
        header[nama.strip().lower()] = nilai.strip()
    return {"method": metode, "path": path, "query": query, "header": header,
            "body": body.strip()}


def tulis_respons(hasil):
    baris = [f"HTTP/1.1 {hasil['status']} {ALASAN[hasil['status']]}"]
    if hasil["body"] is not None:
        baris.append(f"Content-Type: {hasil['jenis']}")
    for nama, nilai in hasil["header"].items():
        baris.append(f"{nama}: {nilai}")
    baris.append("")
    if hasil["body"] is not None:
        baris.append(json.dumps(hasil["body"], ensure_ascii=False))
    return "\r\n".join(baris)


def app(teks_permintaan, ctx):
    return tulis_respons(jalankan_rantai(urai_permintaan(teks_permintaan), ctx))


